class Let(object):
    """Let objects allow capturing intermediate values during glomming.

    This is useful for reusing computed values across multiple keys
    in a dictionary spec without repeating expensive operations.

    Args:

       name: The name to bind the value to (as a string)
       spec: The spec to evaluate and capture

    Example::

        >>> from glom import glom, Let
        >>> target = {'a': 1, 'b': 2}
        >>> glom(target, {
        ...     'total': Let('sum', ['a', 'b']),
        ...     'doubled': ('sum', lambda x: x * 2),
        ... })
        {'total': 3, 'doubled': 6}

    """
    def __init__(self, name, spec):
        self.name = name
        self.spec = spec

    def glomit(self, target, scope):
        val = scope[glom](target, self.spec, scope)
        scope[self.name] = val
        return val

    def __repr__(self):
        return '%s(%r, %r)' % (self.__class__.__name__, self.name, self.spec)


class Iter(object):
    """Iter objects specify that a sub-spec should be applied to each
    item in an iterable.

    Similar to using a list/tuple spec, but with explicit intent and
    potentially different behavior for edge cases.

    Args:

       spec: A glommable sub-spec to apply to each item

    Example::

        >>> from glom import glom, Iter
        >>> target = [{'a': 1}, {'a': 2}]
        >>> glom(target, Iter('a'))
        [1, 2]

    """
    def __init__(self, spec):
        self.spec = spec

    def glomit(self, target, scope):
        if not hasattr(target, '__iter__') or isinstance(target, (str, bytes)):
            raise TypeError("Iter expects an iterable target, got %r" % type(target))
        return [scope[glom](item, self.spec, scope) for item in target]

    def __repr__(self):
        return '%s(%r)' % (self.__class__.__name__, self.spec)


class Fill(object):
    """Fill objects allow setting default values when keys are missing.

    This is particularly useful for working with partially populated
    data structures where you want to ensure certain keys always exist.

    Args:

       fill_spec: A spec to use as the default value for missing keys

    Example::

        >>> from glom import glom, Fill
        >>> target = {'a': 1}
        >>> glom(target, Fill(0))
        {'a': 1}  # Returns target unchanged since all keys present

    Note: Fill works differently than Coalesce - it's about ensuring
    completeness of structure rather than fallback values.

    """
    def __init__(self, fill_spec):
        self.fill_spec = fill_spec

    def glomit(self, target, scope):
        if isinstance(target, dict):
            result = type(target)()
            for key, val in target.items():
                result[key] = scope[glom](val, self.fill_spec, scope)
            return result
        return scope[glom](target, self.fill_spec, scope)

    def __repr__(self):
        return '%s(%r)' % (self.__class__.__name__, self.fill_spec)


class Auto(object):
    """Auto objects enable automatic path resolution.

    When used, glom will attempt to automatically resolve paths by
