        return '%s(%r)' % (cn, self.path)


class Invoke(object):
    """Invoke objects represent callable specs that should be invoked.

    This allows functions and methods to be used directly as specs.

    Args:

       func: A callable to invoke
       args: Positional arguments to pass to the callable
       kwargs: Keyword arguments to pass to the callable

    Example::

        >>> from glom import glom, Invoke
        >>> target = {'data': [1, 2, 3]}
        >>> glom(target, Invoke(len, ('data',)))
        3

    """
    def __init__(self, func, *args, **kwargs):
        self.func = func
        self.args = args
        self.kwargs = kwargs

    def glomit(self, target, scope):
        resolved_args = tuple(scope[glom](arg, self.args, scope) if isinstance(arg, tuple) else arg for arg in self.args)
        resolved_kwargs = {k: scope[glom](v, self.kwargs[k], scope) if isinstance(v, tuple) else v for k, v in self.kwargs.items()}
        return self.func(*resolved_args, **resolved_kwargs)

    def __repr__(self):
        cn = self.__class__.__name__
        if self.kwargs:
            return '%s(%r, %r, %r)' % (cn, self.func, self.args, self.kwargs)
        return '%s(%r, %r)' % (cn, self.func, self.args)
